<script setup lang="ts">
import {ref,computed,watch,nextTick} from 'vue';import {useWorkbench} from '../stores/workbench';import {api,fmt} from '../api/client';import UiIcon from './UiIcon.vue';const s=useWorkbench(),objects=ref<any[]>([]);const pnames:Record<string,string>={PD:'有功负荷',QD:'无功负荷',VMAX:'电压上限',VMIN:'电压下限',PMAX:'有功上限',PMIN:'有功下限',GEN_STATUS:'机组状态',RATE_A:'热稳限额',BR_STATUS:'支路状态'};const whitelist:Record<string,string[]>={bus:['PD','QD','VMAX','VMIN'],gen:['PMAX','PMIN','GEN_STATUS'],branch:['RATE_A','BR_STATUS']};const rules=[{id:'all_in_service',name:'全部在运支路'},{id:'meshed_in_service',name:'网状部分'},{id:'meshed_kv_ge_110',name:'网状且 ≥ 110 kV'}];const opnames:Record<string,string>={switching_limit_per_period:'每时段开关次数上限',switching_limit_total:'开关次数总上限',section_limit:'断面有功限额',switching_penalty:'开关操作惩罚',loss_min:'网损目标',voltage_deviation:'电压偏移目标',multi_period_acopf:'固定拓扑 AC-OPF'};const labels:Record<string,string>={k:'每时段上限 k',K:'总上限 K',beta:'目标系数 β',branches:'断面支路',limit_mw:'限额 / MW',direction:'方向'};const size=computed(()=>s.artifacts?.size);watch(()=>s.focusId,async()=>{await nextTick();document.getElementById('spec-'+s.focusId)?.scrollIntoView({behavior:'smooth',block:'center'})},{immediate:true});async function search(q:string){try{objects.value=(await api('/objects?q='+encodeURIComponent(q))).items}catch{}}function changeTarget(d:any){d.component=d.target.startsWith('B')?'bus':d.target.startsWith('G')?'gen':'branch';if(!whitelist[d.component].includes(d.param))d.param=whitelist[d.component][0];s.markDirty();}function focus(id:string){s.focusId=id;s.tab='code';}async function save(){try{await s.guard(()=>s.save())}catch{}}function addDelta(){s.spec.delta_pi.push({id:'dp-'+(s.spec.delta_pi.length+1),component:'bus',target:'',param:'PD',operation:'scale',direction:null,value:null,periods:[],source:'explicit',evidence:'',inference_chain:null,confirmed:false});s.markDirty();}function opParams(op:any){return Object.keys(op.params||{});}
</script><template><div class="content-pad"><div class="panel-heading"><div><div class="eyebrow">M3 / 模型规格</div><h2>逐项核对本次调整</h2></div><div class="actions"><span class="level-chip">{{s.spec.level_override?.level||s.level}}</span><span class="subtle-pill">v{{s.spec.version}} {{s.confirmed?'已确认':'草稿'}}</span></div></div><section class="spec-section"><div class="section-heading"><div class="icon-label"><span class="math-token">ω</span><h3>基础模型</h3></div><span class="small-note">905 节点算例</span></div><div class="form-grid"><label>问题类型<el-select v-model="s.spec.omega.problem" @change="s.markDirty"><el-option label="多时段 AC-OTS" value="multi_period_ac_ots"/><el-option label="固定拓扑 AC-OPF" value="multi_period_acopf"/></el-select></label><label>时域窗口<div class="static-field">{{s.spec.omega.periods}} 时段 × {{s.spec.omega.step_min}} 分钟</div></label><label>N−1 基础要求<div class="static-field"><el-switch v-model="s.spec.omega.n_minus_1" @change="s.markDirty"/><span>{{s.spec.omega.n_minus_1?'开启':'关闭'}}</span></div></label></div><details class="advanced-spec"><summary>基础模型细节 · 事故集、开断集合与目标</summary><div class="form-grid"><label>事故集<el-select v-model="s.spec.omega.contingency_rule" @change="s.markDirty"><el-option v-for="r in rules" :key="r.id" :value="r.id" :label="r.name"/></el-select></label><label>可开断集合<el-select v-model="s.spec.omega.switchable_rule" @change="s.markDirty"><el-option v-for="r in rules" :key="r.id" :value="r.id" :label="r.name"/></el-select></label><label>基础目标<div class="static-field">偏离当前方式最小 <span class="inference-tag">待确认</span></div></label></div></details></section><section class="spec-section"><div class="section-heading"><div class="icon-label"><span class="math-token">Δπ</span><h3>参数修改</h3><span class="count-pill">{{s.spec.delta_pi.length}} 项</span></div><el-button text size="small" @click="addDelta">＋ 添加条目</el-button></div><el-table v-if="s.spec.delta_pi.length" :data="s.spec.delta_pi" :row-class-name="({row}:any)=>(row.source==='inferred'?'inferred-row ':'')+(s.focusId===row.id?'focused-row':'')" class="spec-table"><el-table-column label="对象" min-width="135"><template #default="{row}"><el-select v-model="row.target" filterable remote allow-create default-first-option :remote-method="search" @change="changeTarget(row)" size="small"><el-option :key="row.target" :label="row.target||'选择编号'" :value="row.target"/><el-option v-for="o in objects.filter(x=>x.id!==row.target)" :key="o.id" :label="o.label||o.id" :value="o.id"/></el-select></template></el-table-column><el-table-column label="参数" min-width="125"><template #default="{row}"><el-select v-model="row.param" size="small" @change="s.markDirty"><el-option v-for="p in whitelist[row.component]||[]" :key="p" :value="p" :label="p"/></el-select><small>{{pnames[row.param]}}</small></template></el-table-column><el-table-column label="操作" min-width="100"><template #default="{row}"><el-select v-model="row.operation" size="small" placeholder="待确认" @change="s.markDirty"><el-option label="按比例" value="scale"/><el-option label="设为" value="set"/><el-option label="增减量" value="add"/></el-select><small v-if="row.direction">{{row.direction==='decrease'?'方向：下降':row.direction==='increase'?'方向：上升':'方向：归零'}}</small></template></el-table-column><el-table-column label="数值" min-width="110"><template #default="{row}"><el-input-number v-model="row.value" size="small" :controls="false" placeholder="待确认" @change="s.markDirty"/></template></el-table-column><el-table-column label="生效时段" min-width="140"><template #default="{row}"><el-select v-model="row.periods" multiple collapse-tags collapse-tags-tooltip size="small" placeholder="全部时段" @change="s.markDirty"><el-option v-for="n in 16" :key="n" :value="n" :label="'第 '+n+' 时段'"/></el-select></template></el-table-column><el-table-column label="来源" width="80"><template #default="{row}"><span :class="row.source==='inferred'?'inference-tag':'explicit-tag'">{{row.source==='inferred'?'推断':'明确'}}</span></template></el-table-column><el-table-column label="定位" width="65"><template #default="{row}"><el-button text size="small" @click="focus(row.id)" :disabled="!s.artifacts?.code"><UiIcon name="code" :size="16"/></el-button></template></el-table-column></el-table><div v-else class="inline-empty">没有参数修改。本次可以仅扩展模型结构。</div><div v-for="d in s.spec.delta_pi" :key="d.id" :id="'spec-'+d.id" class="evidence-row" :class="{inferred:d.source==='inferred',focused:s.focusId===d.id}"><span class="spec-id">{{d.id}}</span><div class="evidence-field"><label>原文依据</label><el-input v-model="d.evidence" size="small" @change="s.markDirty"/><small v-if="d.source==='inferred'">{{(d.inference_chain||[]).join(' → ')}}</small></div><el-checkbox v-if="d.source==='inferred'" v-model="d.confirmed" :disabled="d.value===null||d.value===undefined" @change="s.markDirty">已确认幅度</el-checkbox><button class="text-button danger" @click="s.spec.delta_pi=s.spec.delta_pi.filter((x:any)=>x.id!==d.id);s.markDirty()">删除</button></div><div v-if="s.inferredPending" class="notice amber"><UiIcon name="info"/><span>{{s.parse?.manual_completion?'自动追问已暂停。请在本页填写数值和生效时段，勾选已确认幅度，再保存草稿。':'琥珀色条目来自语义推断。请在左侧回答幅度与时段，逐项确认后才能生成代码。'}}</span></div></section><section class="spec-section"><div class="section-heading"><div class="icon-label"><span class="math-token">s</span><h3>结构修改</h3><span class="count-pill">{{s.spec.structural.length}} 项</span></div><span class="small-note">N−1 属于 ω，不重复生成结构算子</span></div><div v-for="op in s.spec.structural" :key="op.id" :id="'spec-'+op.id" class="operator-card" :class="{focused:s.focusId===op.id}"><div class="section-heading"><strong><span class="spec-id">{{op.id}}</span> {{opnames[op.op_id]||op.op_id}}</strong><el-button text size="small" :disabled="!s.artifacts?.code" @click="focus(op.id)">查看代码</el-button></div><div class="form-grid"><label v-for="key in opParams(op)" :key="key">{{labels[key]||key}}<el-select v-if="key==='branches'" v-model="op.params[key]" multiple filterable allow-create default-first-option @change="s.markDirty"><el-option v-for="b in op.params[key]||[]" :key="b" :label="b" :value="b"/></el-select><el-select v-else-if="key==='direction'" v-model="op.params[key]" @change="s.markDirty"><el-option value="forward" label="首端正向"/><el-option value="both" label="双向"/><el-option value="reverse" label="反向"/></el-select><el-input-number v-else-if="typeof op.params[key]==='number'||op.params[key]===null" v-model="op.params[key]" :controls="false" placeholder="待填写" @change="s.markDirty"/><el-input v-else v-model="op.params[key]" @change="s.markDirty"/></label></div><p class="small-note">原文依据：{{op.evidence}}</p><div v-if="op.op_id==='switching_penalty'&&op.params.beta===null" class="notice amber">β 未指定：生成模板使用配置默认值，并在校验中告警。</div><div v-if="op.custom_code" class="notice amber"><strong>自定义代码 · 待人工审核</strong><pre class="json-block">{{op.custom_code}}</pre></div></div><div v-if="!s.spec.structural.length" class="inline-empty">没有结构修改，沿用基础模型。</div></section><details class="spec-section compact-details"><summary>求解要求 <span>黑盒参数 · 按需配置</span></summary><div class="form-grid"><label>求解器<el-select v-model="s.spec.solver_req.solver" @change="s.markDirty"><el-option v-for="o in [{label:'Mock · 黑盒占位',value:'mock'},{label:'IPOPT',value:'ipopt'},{label:'COPT',value:'copt'},{label:'Gurobi',value:'gurobi'},{label:'外部求解器',value:'external'}]" :key="o.value" v-bind="o"/></el-select></label><label>时限 / 秒<el-input-number v-model="s.spec.solver_req.time_limit_s" :min="1" :controls="false" @change="s.markDirty"/></label><label>收敛容差<el-input-number v-model="s.spec.solver_req.tolerance" :precision="8" :step="0.000001" :controls="false" @change="s.markDirty"/></label></div></details><section v-if="size" class="scale-summary"><div class="section-heading"><h3>完整窗口规模估算</h3><span class="small-note">按模板逐块计数 · {{size.periods}} 时段</span></div><div class="scale-counts"><div><span>0–1 变量</span><strong>{{fmt(size.binary,0)}}</strong></div><div><span>连续变量</span><strong>{{fmt(size.continuous,0)}}</strong></div><div><span>约束</span><strong>{{fmt(size.constraints,0)}}</strong></div></div><div class="switching-scales"><div v-for="r in rules" :key="r.id"><span>{{r.name}}</span><strong>{{fmt(size.switching_counts?.[r.id],0)}}</strong></div></div><p class="small-note">{{size.n1_note}}</p></section><div v-if="s.requiredValueCount&&!s.inferredPending" class="notice amber">还有 {{s.requiredValueCount}} 项修改缺少必填值，补全后再确认。</div><div class="panel-bottom-actions"><div class="actions"><el-button @click="s.step=2">退回修改</el-button><el-button @click="save" :loading="s.busy">{{s.dirty?'保存草稿并更新预览':'更新公式预览'}}</el-button></div><el-button type="primary" :disabled="!s.canConfirm" :loading="s.busy" @click="s.confirm().catch(()=>{})" data-testid="confirm-spec">确认并生成代码</el-button></div><div v-if="s.confirmed" class="notice success"><UiIcon name="check"/><span>v{{s.spec.version}} 已保存，可查看公式、代码或运行五层校验。</span><el-button text @click="s.tab='checks';s.step=4">去校验</el-button></div></div></template>